// Installs a representative set of registry items into fresh apps generated by
// `shadcn init --template <t>` and checks they type-check and build — proof
// that the ds-* components are framework-agnostic (not just Next.js).
//
//   node scripts/test-consumers.mjs                 # all templates
//   node scripts/test-consumers.mjs vite astro      # only some
//
// Requires network access (npm + shadcn CLI) and `make registry` beforehand.
import { spawn, spawnSync } from "child_process"
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "fs"
import { tmpdir } from "os"
import { join } from "path"

const PORT = 8765
const ITEMS = [
  "tokens",
  "ds-link-provider",
  "ds-header-mega",
  "ds-footer-menu",
  "ds-geomap-chart",
  "ds-globe-3d",
  "ds-card-stat",
  "ds-toggle-theme",
].map((n) => `@lema-ds/${n}`)

// Per template: import alias for the app source, the router link, where to
// write the demo, and how to wire it into a page.
const TEMPLATES = {
  next: {
    alias: "@",
    routerImport: '"use client"\n\nimport Link from "next/link"',
    link: "Link",
    demo: "components/demo.tsx",
    wire: () =>
      writeFile(
        "app/page.tsx",
        `import { Demo } from "@/components/demo"\nexport default function Page() { return <Demo /> }\n`
      ),
    check: ["npx", "tsc", "--noEmit"],
    build: ["npm", "run", "build"],
  },
  vite: {
    alias: "@",
    link: "({ href, ...p }) => <a href={href} {...p} />",
    demo: "src/demo.tsx",
    wire: () =>
      writeFile(
        "src/App.tsx",
        `import { Demo } from "@/demo"\nexport default function App() { return <Demo /> }\n`
      ),
    check: ["npx", "tsc", "-b"],
    build: ["npm", "run", "build"],
  },
  "react-router": {
    alias: "~",
    routerImport: 'import { Link } from "react-router"',
    link: "({ href, ...p }) => <Link to={href} {...p} />",
    demo: "app/demo.tsx",
    wire: () =>
      writeFile(
        "app/routes/home.tsx",
        `import { Demo } from "~/demo"\nexport default function Home() { return <Demo /> }\n`
      ),
    check: ["npm", "run", "typecheck"],
    build: ["npm", "run", "build"],
  },
  start: {
    alias: "@",
    routerImport: 'import { Link } from "@tanstack/react-router"',
    link: "({ href, ...p }) => <Link to={href} {...p} />",
    demo: "src/demo.tsx",
    wire: () =>
      writeFile(
        "src/routes/index.tsx",
        `import { createFileRoute } from "@tanstack/react-router"\nimport { Demo } from "@/demo"\n\nexport const Route = createFileRoute("/")({ component: Demo })\n`
      ),
    check: ["npm", "run", "typecheck"],
    build: ["npm", "run", "build"],
  },
  astro: {
    alias: "@",
    link: "({ href, ...p }) => <a href={href} {...p} />",
    demo: "src/demo.tsx",
    wire: () =>
      writeFile(
        "src/pages/index.astro",
        `---\nimport Layout from "@/layouts/main.astro"\nimport { Demo } from "@/demo"\n---\n\n<Layout>\n  <Demo client:load />\n</Layout>\n`
      ),
    check: ["npm", "run", "typecheck"],
    build: ["npm", "run", "build"],
  },
}

let cwd = process.cwd()
const writeFile = (rel, content) => writeFileSync(join(cwd, rel), content)

function run(cmd, args, opts = {}) {
  const r = spawnSync(cmd, args, {
    cwd,
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
    ...opts,
  })
  return { ok: r.status === 0, out: `${r.stdout ?? ""}${r.stderr ?? ""}` }
}

function demoSource(t) {
  const a = t.alias
  return `${t.routerImport ?? ""}
import { HeaderMega } from "${a}/components/ui/ds-header-mega"
import { FooterMenu } from "${a}/components/ui/ds-footer-menu"
import { DynamicGlobe3D } from "${a}/components/ui/ds-globe-3d"
import { DynamicGeoMapChart } from "${a}/components/ui/ds-geomap-chart"
import { ToggleTheme } from "${a}/components/ui/ds-toggle-theme"
import { DSLinkProvider } from "${a}/components/ui/ds-link-provider"

export function Demo() {
  return (
    <DSLinkProvider link={${t.link}}>
      <HeaderMega brand={{ title: "App", href: "/" }} navItems={[{ label: "Home", href: "/" }]} />
      <FooterMenu data={[]} />
      <DynamicGlobe3D />
      <DynamicGeoMapChart geoData={{ type: "FeatureCollection", features: [] }} />
      <ToggleTheme />
    </DSLinkProvider>
  )
}
`
}

if (!existsSync("public/r/ds-header-mega.json")) {
  console.error("public/r is empty — run `make registry` first.")
  process.exit(1)
}

// The registry is served from a child process: `spawnSync` blocks this
// process's event loop, so an in-process server could never answer the CLI.
const server = spawn(
  process.execPath,
  [
    "-e",
    `const http=require("http"),fs=require("fs"),path=require("path");
http.createServer((q,r)=>{try{const f=decodeURIComponent(q.url.split("?")[0]).replace(/^\\//,"");
r.writeHead(200,{"content-type":"application/json"}).end(fs.readFileSync(path.join("public/r",f)))}
catch{r.writeHead(404).end()}}).listen(${PORT})`,
  ],
  { stdio: "ignore" }
)
process.on("exit", () => server.kill())

const requested = process.argv.slice(2)
const names = requested.length ? requested : Object.keys(TEMPLATES)
const root = mkdtempSync(join(tmpdir(), "lema-consumers-"))
const results = []

for (const name of names) {
  const t = TEMPLATES[name]
  if (!t) {
    console.error(
      `Unknown template "${name}". Options: ${Object.keys(TEMPLATES).join(", ")}`
    )
    process.exit(1)
  }
  console.log(`\n▶ ${name}`)
  const step = (label, res) => {
    console.log(`  ${res.ok ? "✔" : "✘"} ${label}`)
    if (!res.ok) console.log(res.out.split("\n").slice(-25).join("\n"))
    return res.ok
  }

  cwd = root
  const app = `app-${name}`
  let ok = step(
    "shadcn init (radix)",
    run("npx", [
      "shadcn@latest",
      "init",
      "--name",
      app,
      "--preset",
      "nova",
      "--base",
      "radix",
      "--template",
      name,
      "--yes",
    ])
  )
  if (ok) {
    cwd = join(root, app)
    const cfgPath = join(cwd, "components.json")
    const cfg = JSON.parse(readFileSync(cfgPath, "utf-8"))
    cfg.registries = {
      ...cfg.registries,
      "@lema-ds": `http://localhost:${PORT}/{name}.json`,
    }
    writeFileSync(cfgPath, JSON.stringify(cfg, null, 2))
    ok = step(
      "shadcn add (8 items)",
      run("npx", ["shadcn@latest", "add", ...ITEMS, "--yes", "--overwrite"])
    )
  }
  if (ok) {
    writeFile(t.demo, demoSource(t))
    t.wire()
    ok = step("typecheck", run(t.check[0], t.check.slice(1)))
  }
  if (ok) ok = step("build", run(t.build[0], t.build.slice(1)))
  results.push([name, ok])
}

server.kill()
console.log(`\nWorkdir: ${root}`)
console.table(
  Object.fromEntries(results.map(([n, ok]) => [n, ok ? "PASS" : "FAIL"]))
)
process.exit(results.every(([, ok]) => ok) ? 0 : 1)
